// PersonLookupRequest is a request body of KUAA's API.
type PersonLookupRequest struct {
	// The CPF, as text, with or without punctuation; its check digits are verified before anything is asked.
	Cpf string `json:"cpf"`
	// aml also asks AML Vínculos: PEP, and óbito with its date. Absent asks Cadastro PF Plus alone.
	Include []string `json:"include,omitempty"`
	// Why the lookup is made (LGPD art. 6, I), recorded with it with its legal basis: onboarding (art. 7, V), fraud_prevention (art. 7, IX), legal_obligation (art. 7, II), credit_protection (art. 7, X), contract_execution (art. 7, V).
	Purpose string `json:"purpose"`
}

// The policy version that produced the decision: its id, version and content digest.
type Policy struct {
	Digest  string `json:"digest"`
	ID      string `json:"id"`
	Version string `json:"version"`
}

// Relationship is an object of KUAA's API.
type Relationship struct {
	Direct      bool   `json:"direct"`
	FromPartyID string `json:"from_party_id"`
	ID          string `json:"id"`
	// Reads "from_party_id is <role> of to_party_id".
	Role string `json:"role"`
	// The stake held, when the relationship is a shareholding.
	SharePercent *float64 `json:"share_percent,omitempty"`
	ToPartyID    string   `json:"to_party_id"`
	ValidFrom    *string  `json:"valid_from,omitempty"`
	ValidTo      *string  `json:"valid_to,omitempty"`
}

// Review is an object of KUAA's API.
type Review struct {
	Action string `json:"action"`
	ID     string `json:"id"`
	// The reviewer's note. Free text that may name the person, so present only for a key with party.pii.view.
	Reason     *string  `json:"reason,omitempty"`
	RecordedAt string   `json:"recorded_at"`
	Requested  []string `json:"requested"`
}

// Run is an object of KUAA's API.
type Run struct {
	CaseID       string `json:"case_id"`
	CurrentState string `json:"current_state"`
	// False when the answer comes from the organization's sandbox: synthetic data, engine doubles chosen by the documented magic values, nothing billed and no official source consulted. True in production.
	Livemode bool   `json:"livemode"`
	Status   string `json:"status"`
	// The status in the vocabulary of the Brazilian KYC market, beside status, which keeps its values: PROCESSING (open, processing, awaiting_input), PENDING_OCR (in_review because a document reading check -- OCR or validation -- failed or timed out), PENDING (in_review, waiting for a human decision), APPROVED (approved), REPROVED (rejected), BLOCKED (rejected by the policy's block outcome, such as a confirmed sanctions match), CANCELLED (cancelled) and EXPIRED (expired). CANCELLED and EXPIRED are closed without a decision. It never changes the decision.
	StatusMarket string `json:"status_market"`
	UpdatedAt    string `json:"updated_at"`
	// What the run waits for: capture or information (answered by POST /v1/cases/{id}/submit), review (answered by a reviewer), or null when it waits for nothing.
	WaitingFor *string `json:"waiting_for"`
	// The workflow version the case is pinned to.
	Workflow RunWorkflow `json:"workflow"`
}

// The workflow version the case is pinned to.
type RunWorkflow struct {
	Digest  string `json:"digest"`
	ID      string `json:"id"`
	Version int64  `json:"version"`
}

// Screening is an object of KUAA's API.
type Screening struct {
	CaseID    string `json:"case_id"`
	CheckedAt string `json:"checked_at"`
	// The outcome of the screening step: hit, no_hit or possible_match. It is not a decision about a case.
	Decision string `json:"decision"`
	List     string `json:"list"`
}

// ScreeningMatch is an object of KUAA's API.
type ScreeningMatch struct {
	// confirmed: the full CPF or CNPJ is listed. strong: the name and another attribute agree. possible: the name alone.
	Classification string `json:"classification"`
	List           string `json:"list"`
	MatchStatus    string `json:"match_status"`
	// For a PEP: whether the five-year window after the function is still open.
	PepActive *bool   `json:"pep_active,omitempty"`
	Score     float64 `json:"score"`
	// The source the entry is listed in, such as cgu_ceis, cgu_pep, ofac_sdn.
	Source string `json:"source"`
	// The version of the source that was read.
	SourceVersion string `json:"source_version"`
}

// ScreeningSource is an object of KUAA's API.
type ScreeningSource struct {
	List        string `json:"list"`
	RetrievedAt string `json:"retrieved_at"`
	Source      string `json:"source"`
	Version     string `json:"version"`
}

// StatementEntry is an object of KUAA's API.
type StatementEntry struct {
	// Signed, in the smallest unit: negative leaves the wallet, positive enters it.
	Amount       int64  `json:"amount"`
	At           string `json:"at"`
	BalanceAfter int64  `json:"balance_after"`
	// The case a charge was for.
	CaseID *string `json:"case_id"`
	// The check a charge was for.
	Check *string `json:"check"`
	// The ledger entry.
	ID string `json:"id"`
	// charge for verification work, top_up for credits added, or the wallet operation kind for anything else, such as a reversal or an adjustment.
	Kind             string  `json:"kind"`
	OperationID      string  `json:"operation_id"`
	PriceKey         *string `json:"price_key"`
	PriceListVersion *string `json:"price_list_version"`
	// What a top-up or a reversal was recorded as.
	Reason *string `json:"reason"`
	// The workflow step a charge was for.
	StepSeq *int64 `json:"step_seq"`
}

// SubmitRequest is a request body of KUAA's API.
type SubmitRequest struct {
	// The workflow state the client believes the case waits in. When given and the case is elsewhere, nothing moves and the answer is 409, which makes a repeated submission harmless.
	State *string `json:"state,omitempty"`
}

// Tag is an object of KUAA's API.
type Tag struct {
	CreatedAt string `json:"created_at"`
	ID        string `json:"id"`
	// The tag as the organization named it. A tag never carries personal data.
	Name string `json:"name"`
	// The name reduced to lowercase letters, digits and hyphens. It is fixed when the tag is created and does not change when the tag is renamed, so it is what an integration names a tag by.
	Slug string `json:"slug"`
}

// UnresolvedOwnership is an object of KUAA's API.
type UnresolvedOwnership struct {
	// Whether the gap keeps the ownership unresolved.
	Blocking bool     `json:"blocking"`
	PartyID  string   `json:"party_id"`
	Path     []string `json:"path"`
	// A stable reason code, such as shares_unknown, ownership_incomplete, entity_not_in_registry or no_beneficial_owner_identified.
	Reason string   `json:"reason"`
	Share  *float64 `json:"share"`
}

// Webhook is an object of KUAA's API.
type Webhook struct {
	// Whether events are delivered. An endpoint turned off keeps its deliveries waiting until it is turned on.
	Active     bool    `json:"active"`
	CreatedAt  string  `json:"created_at"`
	DisabledAt *string `json:"disabled_at"`
	// Why the endpoint was turned off: consecutive_failures when its deliveries kept giving up, or what the person who turned it off wrote.
	DisabledReason *string  `json:"disabled_reason"`
	Events         []string `json:"events"`
	// The endpoint identifier.
	ID   string `json:"id"`
	Name string `json:"name"`
	// The https:// address the deliveries go to.
	URL string `json:"url"`
}

// WebhookCreated is an object of KUAA's API.
type WebhookCreated struct {
	// Whether events are delivered. An endpoint turned off keeps its deliveries waiting until it is turned on.
	Active     bool    `json:"active"`
	CreatedAt  string  `json:"created_at"`
	DisabledAt *string `json:"disabled_at"`
	// Why the endpoint was turned off: consecutive_failures when its deliveries kept giving up, or what the person who turned it off wrote.
	DisabledReason *string  `json:"disabled_reason"`
	Events         []string `json:"events"`
	// The endpoint identifier.
	ID   string `json:"id"`
	Name string `json:"name"`
	// The signing secret, in clear, this once. It is stored sealed and never answered again; a request replayed with the same Idempotency-Key answers null here. Lost, it is replaced by rotating the endpoint in the backoffice.
	Secret *string `json:"secret"`
	// The https:// address the deliveries go to.
	URL string `json:"url"`
}

// The body of a webhook delivery. It carries no personal data; read the case through the API.
type WebhookEvent struct {
	Data            WebhookEventData `json:"data"`
	Datacontenttype string           `json:"datacontenttype"`
	// The event id: the same on every delivery of the event and on every retry. Deduplicate on it.
	ID string `json:"id"`
	// urn:kuaa:tenant: and the tenant the event happened in.
	Source      string `json:"source"`
	Specversion string `json:"specversion"`
	// cases/ and the case id.
	Subject string `json:"subject"`
	Time    string `json:"time"`
	Type    string `json:"type"`
}

// WebhookEventData is an object of KUAA's API.
type WebhookEventData struct {
	// Present on every capture_session.* event: the hosted capture session, as answered when its link was issued.
	CaptureSessionID *string `json:"capture_session_id,omitempty"`
	CaseID           string  `json:"case_id"`
	// Present on check.completed.
	CheckID *string `json:"check_id,omitempty"`
	// Present on document.decided: what the reviewer decided about the document. It never decides the case; the reviewer's reason is not sent.
	Decision *string `json:"decision,omitempty"`
	// Present on decision.recorded.
	DecisionID *string `json:"decision_id,omitempty"`
	// Present on document.decided: the decision a reviewer recorded about one document.
	DocumentDecisionID *string `json:"document_decision_id,omitempty"`
	// Present on document.decided: the document the decision is about, as GET /v1/cases/{id}/documents lists it.
	DocumentID *string `json:"document_id,omitempty"`
	// Present on document.decided for a document capture: front, back or single. Absent for a selfie.
	DocumentSide *string `json:"document_side,omitempty"`
	// Present on document.decided for a document capture: its type, such as CNH or RG. Absent for a selfie.
	DocumentType *string `json:"document_type,omitempty"`
	// The environment of the tenant the event happened in. A sandbox event is about synthetic data and engine doubles.
	Environment string `json:"environment"`
	// The event id, the same as the envelope's id.
	EventID string `json:"event_id"`
	// Present on capture_session.finished: when the person sent the capture.
	FinishedAt *string `json:"finished_at,omitempty"`
	// False for an event of the organization's sandbox, true in production.
	Livemode   bool   `json:"livemode"`
	OccurredAt string `json:"occurred_at"`
	// Present on case.created and case.updated of a child case: the case whose workflow opened it. Absent otherwise.
	ParentCaseID *string `json:"parent_case_id,omitempty"`
	// Present on document.decided: what the document answers.
	Requirement *string `json:"requirement,omitempty"`
	// Present on review.recorded.
	ReviewID *string `json:"review_id,omitempty"`
	// What the event left behind: the case's status for case.*, the check's for check.completed, the outcome for decision.recorded, the reviewer's action for review.recorded, finished for capture_session.finished, the session's status after the event (active, expired or revoked) for the other capture_session.* events, and the reviewer's decision about the document (approved, rejected or rerequested) for document.decided.
	Status string `json:"status"`
	// Present on case.created, case.updated and capture_session.finished: The status in the vocabulary of the Brazilian KYC market, beside status, which keeps its values: PROCESSING (open, processing, awaiting_input), PENDING_OCR (in_review because a document reading check -- OCR or validation -- failed or timed out), PENDING (in_review, waiting for a human decision), APPROVED (approved), REPROVED (rejected), BLOCKED (rejected by the policy's block outcome, such as a confirmed sanctions match), CANCELLED (cancelled) and EXPIRED (expired). CANCELLED and EXPIRED are closed without a decision. It never changes the decision.
	StatusMarket *string `json:"status_market,omitempty"`
	// Present on capture_session.consent_given, .document_submitted and .selfie_submitted: the step of the hosted capture the person finished.
	Step     *string `json:"step,omitempty"`
	TenantID string  `json:"tenant_id"`
	Type     string  `json:"type"`
}

// WebhookList is an object of KUAA's API.
type WebhookList struct {
	// The tenant's endpoints, by name.
	Endpoints []Webhook `json:"endpoints"`
}

// WebhookRequest is a request body of KUAA's API.
type WebhookRequest struct {
	// The events the endpoint receives.
	Events []string `json:"events"`
	// What the tenant calls the endpoint.
	Name string `json:"name"`
	// The https:// address the deliveries go to. An address without TLS, with a user or a password, or whose host is or resolves to a loopback, private, link-local, metadata or shared (100.64.0.0/10) address is refused with 422; every attempt checks the address again as it connects.
	URL string `json:"url"`
}

// Workflow is an object of KUAA's API.
type Workflow struct {
	// True when a case of some kind runs this workflow when it names none.
	Default bool `json:"default"`
	// The case kinds that run this workflow by default.
	DefaultFor []string `json:"default_for"`
	// The workflow definition; POST /v1/cases takes it, or its key, as workflow_definition_id.
	ID string `json:"id"`
	// The workflow's key, such as br.kyc.
	Key string `json:"key"`
	// The version a case starting now is pinned to.
	LatestVersion WorkflowVersion `json:"latest_version"`
	Name          string          `json:"name"`
	// Every published version, newest first.
	Versions []WorkflowVersion `json:"versions"`
}

// WorkflowList is an object of KUAA's API.
type WorkflowList struct {
	// False when the answer comes from the organization's sandbox: synthetic data, engine doubles chosen by the documented magic values, nothing billed and no official source consulted. True in production.
	Livemode bool `json:"livemode"`
	// The published workflow definitions of the key's organization, by key. A sandbox answers the copies of the live versions, with the same numbers and digests.
	Workflows []Workflow `json:"workflows"`
}

// WorkflowStep is an object of KUAA's API.
type WorkflowStep struct {
	At    string `json:"at"`
	Event string `json:"event"`
	From  string `json:"from"`
	Seq   int64  `json:"seq"`
	To    string `json:"to"`
}

// The version a case starting now is pinned to.
type WorkflowVersion struct {
	// The digest of the version's document, the same the decision and the dossier name.
	Digest string `json:"digest"`
	// The workflow version, as a case pins it.
	ID          string `json:"id"`
	PublishedAt string `json:"published_at"`
	Version     int64  `json:"version"`
}

